1	package com.example.starter.blind;
2	
3	import org.springframework.http.HttpStatus;
4	
5	/**
6	 * 业务 API 异常，携带明确的 HTTP 状态码与安全提示信息。
7	 * 异常信息不得包含处理代码或席位序号等盲底内容。
8	 */
9	public class ApiException extends RuntimeException {
10	
11	    private final HttpStatus status;
12	
13	    public ApiException(HttpStatus status, String message) {
14	        super(message);
15	        this.status = status;
16	    }
17	
18	    public HttpStatus getStatus() {
19	        return status;
20	    }
21	
22	    /** 400 请求参数不合法。 */
23	    public static ApiException badRequest(String message) {
24	        return new ApiException(HttpStatus.BAD_REQUEST, message);
25	    }
26	
27	    /** 401 操作者头缺失或角色不合法。 */
28	    public static ApiException unauthorized(String message) {
29	        return new ApiException(HttpStatus.UNAUTHORIZED, message);
30	    }
31	
32	    /** 403 权限不足或无权查看揭盲结果。 */
33	    public static ApiException forbidden(String message) {
34	        return new ApiException(HttpStatus.FORBIDDEN, message);
35	    }
36	
37	    /** 404 资源不存在。 */
38	    public static ApiException notFound(String message) {
39	        return new ApiException(HttpStatus.NOT_FOUND, message);
40	    }
41	
42	    /** 409 状态冲突（含异参重放、未批准揭盲等）。 */
43	    public static ApiException conflict(String message) {
44	        return new ApiException(HttpStatus.CONFLICT, message);
45	    }
46	
