25	import org.springframework.web.bind.annotation.RestController;
26	
27	import java.util.Map;
28	
29	/**
30	 * 实验盲法分配与受控揭盲接口。
31	 * 所有写操作必须携带 X-Request-Id；权限校验先于幂等回放。
32	 */
33	@RestController
34	@RequestMapping("/api")
35	public class BlindExperimentController {
36	
37	    static final String OP_EXPERIMENT_CREATE = "experiment.create";
38	    static final String OP_EXPERIMENT_CLOSE = "experiment.close";
39	    static final String OP_ALLOCATION_CREATE = "allocation.create";
40	    static final String OP_ALLOCATION_WITHDRAW = "allocation.withdraw";
41	    static final String OP_UNBLIND_APPLY = "unblind.apply";
42	    static final String OP_UNBLIND_APPROVE = "unblind.approve";
43	
44	    private final ExperimentService experimentService;
45	    private final UnblindService unblindService;
46	    private final IdempotencyService idempotencyService;
47	    private final ActorContext actorContext;
48	
49	    public BlindExperimentController(ExperimentService experimentService,
50	                                     UnblindService unblindService,
51	                                     IdempotencyService idempotencyService,
52	                                     ActorContext actorContext) {
53	        this.experimentService = experimentService;
54	        this.unblindService = unblindService;
55	        this.idempotencyService = idempotencyService;
56	        this.actorContext = actorContext;
57	    }
58	
59	    // ---------------- 实验 ----------------
60	
61	    /** 创建实验（仅 COORDINATOR）；区组数量 2~8，创建后不可改。 */
62	    @PostMapping("/experiments/{experimentId}")
63	    public ResponseEntity<String> createExperiment(
64	            @PathVariable String experimentId,
65	            @Valid @RequestBody CreateExperimentRequest request,
66	            @RequestHeader(IdempotencyService.HEADER_REQUEST_ID) String requestId) {
67	        Actor actor = requireCoordinator();
68	        String expId = RequestTokens.requireId("experimentId", experimentId);
69	        String reqId = RequestTokens.requireRequestId(requestId);
70	        String fingerprint = idempotencyService.fingerprint(OP_EXPERIMENT_CREATE,
71	                Map.of("experimentId", expId, "blockCount", request.blockCount()));
72	        return idempotencyService.runWrite(reqId, OP_EXPERIMENT_CREATE, fingerprint, actor,
73	                () -> IdempotencyService.WriteOutcome.of(HttpStatus.CREATED.value(),
74	                        experimentService.createExperiment(expId, request.blockCount())));
75	    }
76	
77	    /** 查询实验信息（COORDINATOR / REVIEWER 均可）。 */
78	    @GetMapping("/experiments/{experimentId}")
79	    public ExperimentView getExperiment(@PathVariable String experimentId) {
80	        requireActor();
81	        return experimentService.getExperiment(RequestTokens.requireId("experimentId", experimentId));
82	    }
83	
84	    /** 关闭实验（仅 COORDINATOR）；关闭后拒绝新增分配。 */
85	    @PostMapping("/experiments/{experimentId}/close")
86	    public ResponseEntity<String> closeExperiment(
87	            @PathVariable String experimentId,
88	            @RequestHeader(IdempotencyService.HEADER_REQUEST_ID) String requestId) {
89	        Actor actor = requireCoordinator();
90	        String expId = RequestTokens.requireId("experimentId", experimentId);
91	        String reqId = RequestTokens.requireRequestId(requestId);
92	        String fingerprint = idempotencyService.fingerprint(OP_EXPERIMENT_CLOSE,
93	                Map.of("experimentId", expId));
94	        return idempotencyService.runWrite(reqId, OP_EXPERIMENT_CLOSE, fingerprint, actor,
95	                () -> IdempotencyService.WriteOutcome.of(HttpStatus.OK.value(),
96	                        experimentService.close(expId)));
97	    }
98	
99	    // ---------------- 分配 / 退组 / 查询 ----------------
100	
101	    /** 登记参与者（仅 COORDINATOR）：原子领取第一个空位。 */
102	    @PostMapping("/experiments/{experimentId}/participants/{participantId}/allocations")
103	    public ResponseEntity<String> register(
104	            @PathVariable String experimentId,
105	            @PathVariable String participantId,
106	            @RequestHeader(IdempotencyService.HEADER_REQUEST_ID) String requestId) {
107	        Actor actor = requireCoordinator();
108	        String expId = RequestTokens.requireId("experimentId", experimentId);
109	        String pid = RequestTokens.requireId("participantId", participantId);
110	        String reqId = RequestTokens.requireRequestId(requestId);
111	        String fingerprint = idempotencyService.fingerprint(OP_ALLOCATION_CREATE,
112	                Map.of("experimentId", expId, "participantId", pid));
113	        return idempotencyService.runWrite(reqId, OP_ALLOCATION_CREATE, fingerprint, actor,
114	                () -> IdempotencyService.WriteOutcome.of(HttpStatus.CREATED.value(),
115	                        experimentService.register(expId, pid, actor.actorId())));
116	    }
117	
