101	    private TreeSet<String> normalize(String role, List<String> actors) {
102	        if (actors == null || actors.isEmpty()) {
103	            throw ApiException.badRequest(role + " 至少需要一人");
104	        }
105	        TreeSet<String> set = new TreeSet<>();
106	        for (String raw : actors) {
107	            set.add(RequestTokens.requireId(role + " 人员编号", raw));
108	        }
109	        return set;
110	    }
