113	    public record CanonicalRoster(
114	            TreeSet<String> dataCollectors,
115	            TreeSet<String> randomizationCustodians,
116	            TreeSet<String> safetyReviewers) {
117	
118	        /** 同一人同时承担采集与随机化保管的冲突人员（升序）。 */
119	        public List<String> roleOverlap() {
120	            TreeSet<String> overlap = new TreeSet<>(dataCollectors);
121	            overlap.retainAll(randomizationCustodians);
122	            return List.copyOf(overlap);
123	        }
124	
125	        /** 转为可序列化视图。 */
126	        public RosterView toView() {
127	            return new RosterView(List.copyOf(dataCollectors),
128	                    List.copyOf(randomizationCustodians), List.copyOf(safetyReviewers));
129	        }
