151	                    blockedByCollector.getOrDefault(collector, List.of());
152	            TreeSet<String> blockedParticipants = new TreeSet<>();
153	            blocked.forEach(e -> blockedParticipants.add(e.participantId()));
154	            List<String> visible = activeParticipants.stream()
155	                    .filter(p -> !blockedParticipants.contains(p))
156	                    .toList();
157	            scopes.add(new CollectorScopePreviewView(collector, visible, blocked));
158	        }
159	
160	        List<ConflictEvidenceView> allConflicts = blockedByCollector.values().stream()
161	                .flatMap(List::stream)
